import{_ as o,o as t,c as l,a7 as i}from"./chunks/framework.Du_9D64Q.js";const h=JSON.parse('{"title":"Development plugin types","description":"Plugin types for development in Axolotl-PM. Currently supports Folder (with DevTools) and Script (single .php file). Not recommended for distribution.","frontmatter":{"title":"Development plugin types","outline":"deep","description":"Plugin types for development in Axolotl-PM. Currently supports Folder (with DevTools) and Script (single .php file). Not recommended for distribution.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/developers/plugin-docs/plugin-formats/development"}]]},"headers":[],"relativePath":"docs/developers/plugin-docs/plugin-formats/development.md","filePath":"docs/developers/plugin-docs/plugin-formats/development.md","lastUpdated":1790689997000}'),a={name:"docs/developers/plugin-docs/plugin-formats/development.md"};function r(n,e,s,p,d,u){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="development-plugin-types" tabindex="-1">Development plugin types <a class="header-anchor" href="#development-plugin-types" aria-label="Permalink to &quot;Development plugin types&quot;">​</a></h1><p>Since the standard types of plugins are usually pretty difficult to work with while developing a plugin, there are more types of plugins that developers can use, but these are <strong>not</strong> recommended for distribution.</p><h2 id="folder" tabindex="-1">Folder <a class="header-anchor" href="#folder" aria-label="Permalink to &quot;Folder&quot;">​</a></h2><p><strong>Note:</strong> this plugin format is <strong>not</strong> enabled by default. The <a href="https://github.com/pmmp/DevTools/releases" target="_blank" rel="noreferrer">DevTools</a> plugin is required to load this type of plugin.</p><p>This plugin format is similar to a PHAR plugin in structure, but all the files are in a folder on the disk instead of inside a phar file. This gives you easy access to the source code when you’re developing a plugin.</p><p>This plugin format is commonly used for development, because it is just as feature-complete as a PHAR plugin, and can be compiled to a PHAR plugin when you’re ready to release it.</p><p>You can see the <a href="https://github.com/pmmp/ExamplePlugin" target="_blank" rel="noreferrer">ExamplePlugin</a> or any plugin source-code repository to get an idea of how this should look.</p><h3 id="loading" tabindex="-1">Loading <a class="header-anchor" href="#loading" aria-label="Permalink to &quot;Loading&quot;">​</a></h3><ol><li>If you don’t have the <a href="https://github.com/pmmp/DevTools/releases" target="_blank" rel="noreferrer">DevTools</a> plugin, <a href="https://github.com/pmmp/DevTools/releases/latest" target="_blank" rel="noreferrer">download its phar file</a> and put it in your <code>plugins</code> folder.</li><li>Move the folder containing the plugin’s source code into your <code>plugins</code> folder. The plugin’s folder should contain a <code>plugin.yml</code> file and a <code>src</code> folder.</li><li>Restart the server and the plugin will be loaded.</li></ol><h2 id="script" tabindex="-1">Script <a class="header-anchor" href="#script" aria-label="Permalink to &quot;Script&quot;">​</a></h2><p>A script plugin is a single <code>.php</code> file. They’re useful for quickly testing features without creating a full plugin structure.</p><p>There are some key differences between a script plugin and other types of plugins:</p><ul><li>Instead of a <code>plugin.yml</code>, the basic metadata of the plugin is declared in a PHPDoc comment at the top of the file</li><li>You can declare multiple classes, but all of them must be inside the script plugin’s <code>.php</code> file</li><li>Resources and <code>config.yml</code> files are not supported by default</li><li><code>onCommand()</code> is not supported</li><li>Any manifest attribute that accepts arrays or objects (e.g. <code>commands</code>, <code>permissions</code>, <code>authors</code>) is not supported</li></ul><p>Check out the <a href="https://github.com/axolotl-pm/PocketMine-MP/blob/stable/examples/plugins/ExampleScriptPlugin.php" target="_blank" rel="noreferrer">example on GitHub</a>.</p><h3 id="loading-1" tabindex="-1">Loading <a class="header-anchor" href="#loading-1" aria-label="Permalink to &quot;Loading&quot;">​</a></h3><ol><li>Drop the <code>.php</code> file into your <code>plugins</code> folder.</li><li>Restart the server and the plugin will be loaded.</li></ol>',16)])])}const g=o(a,[["render",r]]);export{h as __pageData,g as default};
